"""Regenerate the P4 toast glyphs and palette inks from the CM5 stylesheet."""
import json,zlib,sys
from pathlib import Path
from render import fixture_page

def generate(config,dest):
 chars=sorted(set('Lights onoffBrighteningDimming ·0123456789%No dimmable scene lightsDimming interrupted — check connection?'))
 with fixture_page(config,[]) as page:
  meta=page.locator('#gtoast').evaluate('''(e,chars)=>{const s=getComputedStyle(e),c=document.createElement('canvas'),g=c.getContext('2d',{willReadFrequently:true});c.width=c.height=128;g.font=s.fontWeight+' '+s.fontSize+' '+s.fontFamily;g.fillStyle='white';const font=g.font;return {font,glyphs:chars.map(ch=>{const m=g.measureText(ch),x=-Math.ceil(m.actualBoundingBoxLeft),y=-Math.ceil(m.actualBoundingBoxAscent),w=Math.max(0,Math.ceil(m.actualBoundingBoxRight)-x),h=Math.max(0,Math.ceil(m.actualBoundingBoxDescent)-y);g.clearRect(0,0,128,128);g.fillText(ch,10-x,10-y);return [ch.codePointAt(0),Math.round(m.width*64),x,y,w,h,w&&h?Array.from(g.getImageData(10,10,w,h).data).filter((_,i)=>i%4===3):[]]})}}''',chars)
  inks=[]
  for pal in ('linen','midnight','ember','slate','heath','mono'):
   inks.append(page.evaluate('''pal=>{for(const e of [document.documentElement,document.body]){for(const c of [...e.classList])if(c.startsWith('pal-'))e.classList.remove(c);e.classList.add('pal-'+pal)}return getComputedStyle(document.querySelector('#gtoast')).color.match(/\d+/g).map(Number)}''',pal))
 data=bytearray();records=[]
 for code,advance,x,y,w,h,alpha in meta['glyphs']:
  packed=zlib.compress(bytes(alpha),9) if alpha else b''
  records.append((code,advance,x,y,w,h,len(data),len(packed)));data.extend(packed)
 out=['#pragma once','// Generated by gesture_art.py from the CM5 Architectural toast. '+meta['font'],'namespace study {','struct GestureGlyph {unsigned code;int advance,x,y,w,h;unsigned offset,size;};','constexpr GestureGlyph gesture_glyphs[]={']
 out+=['{'+','.join(map(lambda n:str(int(n)),r))+'},' for r in records];out+=['};','constexpr uint16_t gesture_inks[]={'+','.join(str((r>>3)<<11|(g>>2)<<5|(b>>3)) for r,g,b in inks)+'};','constexpr uint8_t gesture_alpha[]={']
 out+=[','.join(map(str,data[i:i+32]))+',' for i in range(0,len(data),32)];out+=['};','}']
 dest.write_text('\n'.join(out)+'\n',encoding='utf8');print('Toast glyph bytes',len(data))
if __name__=='__main__':
 config=json.loads(Path(sys.argv[1]).read_text())['config'];config['display']['theme']='architectural'
 generate(config,Path(__file__).with_name('gesture_assets.h'))

